function compareNarrative(a,b){const parts=[];if(Number.isFinite(compareValue(a,'population'))&&Number.isFinite(compareValue(b,'population'))&&compareValue(a,'population')!==compareValue(b,'population')){const larger=compareValue(a,'population')>compareValue(b,'population')?a:b;parts.push(`${nameOf(larger)} ${t('insightPopulationLarger')}`)}if(Number.isFinite(a.area)&&Number.isFinite(b.area)&&a.area!==b.area){const largerArea=a.area>b.area?a:b;parts.push(`${nameOf(largerArea)} ${t('insightAreaLarger')}`)}const aDensity=Number.isFinite(compareValue(a,'population'))&&Number.isFinite(a.area)&&a.area>0?compareValue(a,'population')/a.area:null;const bDensity=Number.isFinite(compareValue(b,'population'))&&Number.isFinite(b.area)&&b.area>0?compareValue(b,'population')/b.area:null;if(Number.isFinite(aDensity)&&Number.isFinite(bDensity)&&Math.abs(aDensity-bDensity)>.1){const denser=aDensity>bDensity?a:b;parts.push(`${nameOf(denser)} ${t('insightDenser')}`)}if((a.languages||[]).length&&(b.languages||[]).length){parts.push(`${nameOf(a)} / ${nameOf(b)} · ${t('insightLanguages')}: ${(a.languages||[]).length} / ${(b.languages||[]).length}`)}return parts.join(' · ')||t('comparisonQuestion');}
